import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, spring, Easing } from "remotion";
import { COLORS, FONTS, headlineGradient, ENGRAVE_SHADOW } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

type Side = "left" | "right";
type Row = { label: string; left: number; right: number };

const pct = (v: unknown): number => {
  const n = Number(v);
  return Number.isFinite(n) ? Math.max(0, Math.min(100, n)) : 0;
};

const str = (v: unknown, fallback: string): string =>
  typeof v === "string" && v.trim().length > 0 ? v.trim() : fallback;

const readRows = (raw: unknown, max: number): Row[] => {
  if (!Array.isArray(raw)) return [];
  return raw.slice(0, max).map((item) => {
    const o = (item ?? {}) as Record<string, unknown>;
    return { label: str(o.label, ""), left: pct(o.left), right: pct(o.right) };
  });
};

const ComparisonDuel: React.FC<PrimitiveProps> = ({ anim, fps, dark, format, frame }) => {
  const f = useCurrentFrame();
  const total = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const p = (anim.params ?? {}) as Record<string, unknown>;

  const vertical = format === "portrait";
  const compact = format === "half";

  // scale unit derived from the box we were handed (never from the composition)
  const s = vertical ? frame.width / 1080 : compact ? frame.height / 960 : frame.height / 1080;
  const px = (v: number) => v * s;

  const T = vertical
    ? { pad: 64, gap: 26, title: 76, eyebrow: 22, side: 46, rowLabel: 26, bar: 16, score: 64, badge: 96, panelPad: 34, radius: 24 }
    : compact
    ? { pad: 36, gap: 16, title: 44, eyebrow: 14, side: 28, rowLabel: 18, bar: 10, score: 36, badge: 58, panelPad: 20, radius: 16 }
    : { pad: 72, gap: 30, title: 72, eyebrow: 20, side: 42, rowLabel: 23, bar: 13, score: 56, badge: 88, panelPad: 30, radius: 20 };

  const maxRows = compact ? 3 : 4;
  const rows = readRows(p.rows, maxRows);
  const unit = typeof p.unit === "string" ? p.unit : "%";
  const vsLabel = str(p.vs, "VS");
  const eyebrow = str(p.eyebrow, "");
  const headline = str(anim.text, "");

  const labels: Record<Side, string> = { left: str(p.left, "A"), right: str(p.right, "B") };
  const notes: Record<Side, string> = { left: str(p.leftNote, ""), right: str(p.rightNote, "") };

  const avg = (side: Side): number =>
    rows.length > 0
      ? Math.round(rows.reduce((a, r) => a + r[side], 0) / rows.length)
      : pct(side === "left" ? p.leftScore : p.rightScore);
  const scores: Record<Side, number> = { left: avg("left"), right: avg("right") };

  const autoWinner: Side | "none" =
    scores.left === scores.right ? "none" : scores.left > scores.right ? "left" : "right";
  const winner: Side | "none" =
    p.winner === "left" || p.winner === "right" || p.winner === "none" ? p.winner : autoWinner;

  const txt = dark ? COLORS.textOnDark : COLORS.textOnLight;
  const muted = dark ? COLORS.mutedOnDark : COLORS.mutedOnLight;
  const accents: Record<Side, string> = { left: COLORS.leather, right: COLORS.teal };
  const fills: Record<Side, string> = {
    left: `linear-gradient(90deg, ${COLORS.leather}, ${COLORS.tealBright})`,
    right: `linear-gradient(90deg, ${COLORS.teal}, ${COLORS.gold})`,
  };

  // ---- timing ----------------------------------------------------------
  const titleIn = spring({ frame: f, fps, config: { damping: 200, mass: 0.7 } });
  const enter = (delay: number) => spring({ frame: f - delay, fps, config: { damping: 200, mass: 0.8 } });
  const enterL = enter(5);
  const enterR = enter(8);
  const vsPop = spring({ frame: f - 11, fps, config: { damping: 11, mass: 0.5 } });

  const barStart = 16;
  const stagger = 6;
  const barDur = 22;
  const lastRow = Math.max(0, rows.length - 1);
  const settled = barStart + lastRow * stagger + barDur;

  const rowProgress = (i: number) =>
    interpolate(f, [barStart + i * stagger, barStart + i * stagger + barDur], [0, 1], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.cubic),
    });
  const scoreProgress = interpolate(f, [barStart, settled], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });
  const crown = Math.min(1, spring({ frame: f - settled, fps, config: { damping: 13, mass: 0.6 } }));
  const out = interpolate(f, [total - 8, total - 1], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const renderPanel = (side: Side) => {
    const isWinner = winner === side;
    const accent = accents[side];
    const grow = side === "left" ? enterL : enterR;
    const dir = side === "left" ? -1 : 1;
    const shift = (1 - grow) * px(vertical ? 46 : 96) * dir;
    const lift = isWinner ? crown * px(vertical ? 6 : 10) : 0;

    return (
      <div
        style={{
          flex: 1,
          minWidth: 0,
          display: "flex",
          flexDirection: "column",
          gap: px(compact ? 10 : 14),
          padding: px(T.panelPad),
          borderRadius: px(T.radius),
          background: `${COLORS.vellum}E6`,
          border: "1px solid rgba(255,255,255,0.10)",
          boxShadow: isWinner
            ? `0 0 0 ${px(2)}px ${accent}${crown > 0.5 ? "AA" : "55"}, 0 ${px(18)}px ${px(52)}px rgba(0,0,0,0.45)`
            : `0 ${px(14)}px ${px(40)}px rgba(0,0,0,0.35)`,
          opacity: grow,
          transform: vertical
            ? `translateY(${shift}px) translateY(${-lift}px)`
            : `translateX(${shift}px) translateY(${-lift}px)`,
        }}
      >
        <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", gap: px(12) }}>
          <div
            style={{
              fontFamily: FONTS.display,
              fontWeight: FONTS.displayWeight,
              fontSize: px(T.side),
              lineHeight: 0.95,
              textTransform: "uppercase",
              letterSpacing: "0.01em",
              color: txt,
              textShadow: ENGRAVE_SHADOW,
            }}
          >
            {labels[side]}
          </div>
          <div
            style={{
              fontFamily: FONTS.display,
              fontWeight: FONTS.displayWeight,
              fontSize: px(T.score),
              lineHeight: 0.9,
              flexShrink: 0,
              fontVariantNumeric: "tabular-nums",
              ...(isWinner
                ? {
                    backgroundImage: headlineGradient(),
                    WebkitBackgroundClip: "text",
                    backgroundClip: "text",
                    color: "transparent",
                  }
                : { color: accent }),
            }}
          >
            {Math.round(scores[side] * scoreProgress)}
            <span style={{ fontSize: px(T.score * 0.45) }}>{unit}</span>
          </div>
        </div>

        <div
          style={{
            height: px(3),
            borderRadius: 999,
            background: `linear-gradient(90deg, ${accent}, ${accent}00)`,
            transform: `scaleX(${grow})`,
            transformOrigin: "left center",
          }}
        />

        {notes[side] !== "" ? (
          <div
            style={{
              fontFamily: FONTS.body,
              fontWeight: FONTS.bodyWeight,
              fontSize: px(T.rowLabel * 0.82),
              letterSpacing: "0.14em",
              textTransform: "uppercase",
              color: muted,
              opacity: grow,
            }}
          >
            {notes[side]}
          </div>
        ) : null}

        {rows.map((r, i) => {
          const prog = rowProgress(i);
          const value = r[side];
          return (
            <div key={`${side}-${i}`} style={{ display: "flex", flexDirection: "column", gap: px(6) }}>
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                  gap: px(10),
                  fontFamily: FONTS.body,
                  fontWeight: FONTS.bodyWeight,
                  fontSize: px(T.rowLabel),
                  color: muted,
                }}
              >
                <span style={{ minWidth: 0, textAlign: "left" }}>
                  {r.label}
                </span>
                <span style={{ color: txt, fontWeight: 700, flexShrink: 0, fontVariantNumeric: "tabular-nums" }}>
                  {Math.round(value * prog)}
                  {unit}
                </span>
              </div>
              <div
                style={{
                  height: px(T.bar),
                  borderRadius: 999,
                  background: "rgba(255,255,255,0.08)",
                  overflow: "hidden",
                }}
              >
                <div
                  style={{
                    width: `${value * prog}%`,
                    height: "100%",
                    borderRadius: 999,
                    backgroundImage: fills[side],
                    boxShadow: `0 0 ${px(14)}px ${accent}55`,
                  }}
                />
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  const badgeScale = vsPop * (1 + 0.035 * Math.sin(f / 6));

  return (
    <AbsoluteFill
      style={{
        fontFamily: FONTS.body,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        padding: px(T.pad),
        opacity: out,
      }}
    >
      {(eyebrow !== "" || headline !== "") && (
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: px(8),
            marginBottom: px(vertical ? 34 : compact ? 14 : 26),
            opacity: titleIn,
            transform: `translateY(${(1 - titleIn) * px(-26)}px)`,
          }}
        >
          {eyebrow !== "" ? (
            <div
              style={{
                fontFamily: FONTS.body,
                fontWeight: 600,
                fontSize: px(T.eyebrow),
                letterSpacing: "0.22em",
                textTransform: "uppercase",
                color: muted,
              }}
            >
              {eyebrow}
            </div>
          ) : null}
          {headline !== "" ? (
            <div
              style={{
                fontFamily: FONTS.display,
                fontWeight: FONTS.displayWeight,
                fontSize: px(T.title),
                lineHeight: 0.92,
                textTransform: "uppercase",
                textAlign: "center",
                maxWidth: vertical ? "96%" : compact ? "94%" : "78%",
                backgroundImage: headlineGradient(),
                WebkitBackgroundClip: "text",
                backgroundClip: "text",
                color: "transparent",
              }}
            >
              {headline}
            </div>
          ) : null}
        </div>
      )}

      <div
        style={{
          width: "100%",
          display: "flex",
          flexDirection: vertical ? "column" : "row",
          alignItems: "stretch",
          justifyContent: "center",
          gap: px(T.gap),
        }}
      >
        {renderPanel("left")}
        <div
          style={{
            alignSelf: "center",
            flexShrink: 0,
            width: px(T.badge),
            height: px(T.badge),
            borderRadius: 999,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            background: `${COLORS.ink}E6`,
            border: `${px(2)}px solid ${COLORS.teal}66`,
            boxShadow: `0 0 ${px(30)}px ${COLORS.teal}33, 0 ${px(10)}px ${px(28)}px rgba(0,0,0,0.4)`,
            transform: `scale(${Math.max(0, badgeScale)})`,
          }}
        >
          <span
            style={{
              fontFamily: FONTS.display,
              fontWeight: FONTS.displayWeight,
              fontSize: px(T.badge * 0.4),
              lineHeight: 1,
              letterSpacing: "0.02em",
              textTransform: "uppercase",
              backgroundImage: headlineGradient(),
              WebkitBackgroundClip: "text",
              backgroundClip: "text",
              color: "transparent",
            }}
          >
            {vsLabel}
          </span>
        </div>
        {renderPanel("right")}
      </div>
    </AbsoluteFill>
  );
};

export default ComparisonDuel;

