import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, spring, Easing } from "remotion";
import { COLORS, FONTS, headlineGradient, ENGRAVE_SHADOW } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const asNum = (v: unknown, d: number): number =>
  typeof v === "number" && Number.isFinite(v) ? v : d;

const asStr = (v: unknown, d: string): string =>
  typeof v === "string" && v.trim().length > 0 ? v.trim() : d;

// neutral hairline / well — allowed because it carries no hue
const NEUTRAL_LINE = "rgba(127,127,127,0.28)";

const ComparisonDuel: React.FC<PrimitiveProps> = ({ anim, fps, dark, format, frame }) => {
  const f = useCurrentFrame();
  const total = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const p = (anim.params ?? {}) as Record<string, unknown>;

  const labels = { left: asStr(p.left, "Before"), right: asStr(p.right, "After") };
  const subs = { left: asStr(p.leftSub, ""), right: asStr(p.rightSub, "") };
  const values = { left: asNum(p.leftValue, 100), right: asNum(p.rightValue, 100) };
  const unit = asStr(p.unit, "");
  const winner = p.winner === "left" ? "left" : p.winner === "none" ? "none" : "right";
  const showDelta = p.showDelta !== false;

  // portrait stacks the two sides; half + landscape run them as a row
  const row = format !== "portrait";
  const S =
    format === "landscape" ? frame.height : format === "half" ? frame.height * 1.1 : frame.width;
  const pad = Math.min(frame.width, frame.height) * 0.075;

  const ink = dark ? COLORS.textOnDark : COLORS.textOnLight;
  const muted = dark ? COLORS.mutedOnDark : COLORS.mutedOnLight;

  const pop = (delay: number, damping = 16): number =>
    spring({ frame: Math.max(0, f - delay), fps, config: { damping, stiffness: 130, mass: 0.9 } });

  const barStart = Math.round(fps * 0.45);
  const barDur = Math.max(1, Math.round(fps * 0.9));
  const bp = interpolate(f, [barStart, barStart + barDur], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });
  const wp = pop(barStart + barDur, 11);
  const intro = pop(0);
  const vs = pop(Math.round(fps * 0.18), 10);
  const out = interpolate(f, [total - Math.round(fps * 0.25), total], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const maxV = Math.max(Math.abs(values.left), Math.abs(values.right), 1);
  const titleSize = S * (format === "half" ? 0.044 : 0.05);
  const valueSize = S * (row ? 0.1 : 0.115);
  const labelSize = S * 0.028;
  const subSize = S * 0.023;
  const badge = S * 0.11;
  const radius = S * 0.022;
  const ring = Math.max(2, S * 0.003);

  const count = (t: number): string =>
    Number.isInteger(t) ? String(Math.round(t * bp)) : (t * bp).toFixed(1);

  const delta =
    values.left !== 0 ? ((values.right - values.left) / Math.abs(values.left)) * 100 : 0;
  const deltaLabel = `${delta > 0 ? "+" : ""}${Math.round(delta)}%`;

  const side = (key: "left" | "right") => {
    const isWin = winner === key;
    const s = key === "left" ? intro : pop(Math.round(fps * 0.08));
    const dir = key === "left" ? -1 : 1;
    const barW = Math.min(100, Math.max(4, (Math.abs(values[key]) / maxV) * 100 * bp));
    return (
      <div
        style={{
          position: "relative",
          flex: 1,
          minWidth: 0,
          boxSizing: "border-box",
          padding: S * 0.034,
          borderRadius: radius,
          background: COLORS.vellum,
          border: `1px solid ${NEUTRAL_LINE}`,
          boxShadow: "0 18px 46px rgba(0,0,0,0.35)",
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          gap: S * 0.014,
          opacity: s,
          transform: `translateX(${dir * (1 - s) * S * 0.16}px) scale(${isWin ? 1 + 0.05 * wp : 1})`,
        }}
      >
        <div
          style={{
            fontFamily: FONTS.body,
            fontWeight: 600,
            fontSize: labelSize,
            letterSpacing: "0.18em",
            textTransform: "uppercase",
            whiteSpace: "nowrap",
            overflow: "hidden",
            textOverflow: "ellipsis",
            color: isWin ? COLORS.teal : muted,
          }}
        >
          {labels[key]}
        </div>

        <div
          style={{
            fontFamily: FONTS.display,
            fontWeight: FONTS.displayWeight,
            fontSize: valueSize,
            lineHeight: 0.95,
            letterSpacing: "-0.01em",
            ...(isWin
              ? {
                  backgroundImage: headlineGradient(),
                  WebkitBackgroundClip: "text",
                  backgroundClip: "text",
                  color: "transparent",
                }
              : { color: ink, textShadow: ENGRAVE_SHADOW }),
          }}
        >
          {count(values[key])}
          {unit ? <span style={{ fontSize: valueSize * 0.45 }}>{unit}</span> : null}
        </div>

        <div
          style={{
            height: S * 0.012,
            borderRadius: 999,
            background: NEUTRAL_LINE,
            overflow: "hidden",
          }}
        >
          <div
            style={{
              height: "100%",
              width: `${barW}%`,
              borderRadius: 999,
              background: isWin ? headlineGradient() : COLORS.inkSoft,
            }}
          />
        </div>

        {subs[key] && format !== "half" ? (
          <div
            style={{
              fontFamily: FONTS.body,
              fontWeight: FONTS.bodyWeight,
              fontSize: subSize,
              lineHeight: 1.3,
              color: muted,
              whiteSpace: "nowrap",
              overflow: "hidden",
              textOverflow: "ellipsis",
            }}
          >
            {subs[key]}
          </div>
        ) : null}

        {isWin ? (
          <div
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              right: 0,
              bottom: 0,
              borderRadius: radius,
              border: `${ring}px solid ${COLORS.teal}`,
              opacity: wp * 0.9,
              pointerEvents: "none",
            }}
          />
        ) : null}
      </div>
    );
  };

  return (
    <AbsoluteFill
      style={{
        fontFamily: FONTS.body,
        alignItems: "center",
        justifyContent: "center",
        padding: pad,
        boxSizing: "border-box",
        opacity: out,
      }}
    >
      <div
        style={{
          width: "100%",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          gap: S * 0.03,
        }}
      >
        {anim.text ? (
          <div
            style={{
              fontFamily: FONTS.display,
              fontWeight: FONTS.displayWeight,
              fontSize: titleSize,
              lineHeight: 1,
              letterSpacing: "0.02em",
              textTransform: "uppercase",
              textAlign: "center",
              color: ink,
              textShadow: ENGRAVE_SHADOW,
              opacity: intro,
              transform: `translateY(${(1 - intro) * -S * 0.03}px)`,
            }}
          >
            {anim.text}
          </div>
        ) : null}

        <div
          style={{
            width: "100%",
            display: "flex",
            flexDirection: row ? "row" : "column",
            alignItems: row ? "stretch" : "center",
            justifyContent: "center",
            gap: S * 0.022,
          }}
        >
          {side("left")}

          <div
            style={{
              flex: "0 0 auto",
              alignSelf: "center",
              width: badge,
              height: badge,
              borderRadius: 999,
              background: COLORS.ink,
              border: `${ring}px solid ${COLORS.teal}`,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontFamily: FONTS.display,
              fontWeight: FONTS.displayWeight,
              fontSize: badge * 0.42,
              letterSpacing: "0.04em",
              color: COLORS.tealBright,
              boxShadow: "0 10px 30px rgba(0,0,0,0.4)",
              transform: `scale(${vs}) rotate(${(1 - vs) * -25}deg)`,
              zIndex: 2,
            }}
          >
            VS
          </div>

          {side("right")}
        </div>

        {showDelta && values.left !== 0 && format !== "half" ? (
          <div
            style={{
              flex: "0 0 auto",
              background: COLORS.ink,
              border: `1px solid ${NEUTRAL_LINE}`,
              borderRadius: 999,
              padding: `${S * 0.012}px ${S * 0.032}px`,
              fontFamily: FONTS.mono,
              fontSize: S * 0.026,
              letterSpacing: "0.12em",
              color: COLORS.tealBright,
              opacity: wp,
              transform: `translateY(${(1 - wp) * S * 0.02}px)`,
            }}
          >
            {deltaLabel}
          </div>
        ) : null}
      </div>
    </AbsoluteFill>
  );
};

export default ComparisonDuel;
